  async function page(path){
    if(!getState().user){navigate(`/entrar?next=${encodeURIComponent(path+location.search)}`,{replace:true});return el("div",{class:"shop-loading"},"Abrindo seu acesso…");}
    let content;
    if(path==="/conta")content=await overview();
    else if(path==="/conta/colecao")content=await collectionUI.dashboard(path);
    else if(path==="/conta/colecao/adicionar")content=await collectionUI.wizard();
    else if(path==="/conta/colecao/colecoes")content=await setsPage();
    else if(path.startsWith("/conta/colecao/colecoes/"))content=await checklistPage(decodeURIComponent(path.split("/").at(-1)));
    else if(path==="/conta/colecao/cartas")content=await collectionUI.dashboard(path);
    else if(path==="/conta/colecao/faltantes")content=await checklistPage();
    else if(path==="/conta/colecao/valores")content=await valuationPage();
    else if(path==="/conta/colecao/importar")content=await csvPage();
    else if(path==="/conta/desejos")content=await wishlistPage();
    else if(path==="/conta/dados")content=await profilePage();
    else if(path==="/conta/enderecos")content=await addressesPage();
    else if(path==="/conta/preferencias")content=await preferencesPage();
    else if(path==="/conta/seguranca")content=await securityPage();
    else if(path==="/conta/notificacoes")content=await notificationsPage();
    else if(path==="/conta/pedidos"){const data=await api("/account/orders");content=el("div",{},title("ACOMPANHE CADA DESCOBERTA","Meus pedidos."),arr(data.items).length?ordersList(data.items):empty("Seu próximo pedido começa na loja.","Os pedidos desta conta serão exibidos aqui.",link("Explorar loja","/busca","shop-button")));}
    else content=empty("Esta página não foi encontrada.","Escolha uma das áreas da sua conta.",link("Minha conta","/conta","shop-button secondary"));
    return frame(path,content);
  }
